INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(88753, 'ruRU', '', '"Алунет будет противиться тем, кто попытается взять её в руки. Своевольный дух великого посоха нужно сперва сломить."$b$b— Магна Айгвинн', 24330),
(88754, 'ruRU', '', '"Алунет своенравна. Её нужно быстро привязать к призывающему, пока любопытство не увело её прочь."$b$b— Магна Айгвинн', 24330),
(88755, 'ruRU', '', '"Сила Алунет должна быть сразу очевидна любому, кто возьмёт её в руки. Но её тонкости станут заметны лишь со временем."$b$b— Магна Айгвинн', 24330),
(88756, 'ruRU', '', '"Когда Алунет не используется, ей нужно позволять возвращаться в свой собственный план."$b$b— Магна Айгвинн', 24330),
(88768, 'ruRU', '', 'Аххх... Алунет. Ты говоришь о великом посохе Магны.$b$bЯ с самого начала знала, что это не обычное оружие. Моя госпожа просто протягивала руку вверх и ХВАТАЛА посох прямо из воздуха, немного размахивала им, а затем... просто ВОЗВРАЩАЛА его обратно в тот же воздух, откуда он появился.$b$bНикакой маскировки или шарлатанской невидимости тут не было. Этот посох пришёл из другого мира. И Магна знала, как дотянуться до этого мира и достать его оттуда.', 24330),
(88769, 'ruRU', '', 'Однажды я видела это великое оружие в библиотеке госпожи — оно само двигалось среди стеллажей!$b$bЯ сделала вид, что не заметила, но, боюсь, оно почувствовало мой взгляд.', 24330),
(88770, 'ruRU', '', 'Ты про оружие Магны? Я расскажу тебе, что знаю.$b$bОднажды, когда я была намного, намного младше, я потянулась коснуться великого посоха — госпожа оставила его прислонённым к двери своих покоев. Посох отверг моё прикосновение болезненными щупальцами розовых и фиолетовых молний.$b$bНе прошло и секунды, как появилась Магна и вырвала оружие у меня из рук.$b$bЕё с этим посохом связывали мощные узы — я никогда не пойму этого до конца.', 24330),
(88771, 'ruRU', '', 'Это оружие... я никогда не видела ничего подобного.$b$bМоя госпожа разговаривала с ним, будто оно живое. Говорила о заклинаниях, ритуалах, прочих тайнах тайной магии... всё это было выше моего понимания.$b$bОна всегда была немного дикой, моя госпожа, но сумасшедшей мне никогда не казалась. Хотя разговаривать с посохом — это, конечно, странно.', 24330),
(88772, 'ruRU', '', 'Что ты можешь рассказать мне об Алунет?', 24330),
(88931, 'ruRU', '', 'Джик на то. Джик на это. А ну забери свои слова, дукер $r!', 24330),
(88932, 'ruRU', '', 'Манкасибо, $g господин:госпожа;. МАНКАСИБО!', 24330),
(88933, 'ruRU', '', 'Бликети-сликети ук. Этот манк наджикал на моего дука. Вот так! А ну гони Бойцовский корм!', 24330),
(88934, 'ruRU', '', 'Ты переплюнул меня, викет-любитель. Вот, забирай корм. Ты его заслужил.', 24330),
(88935, 'ruRU', '', 'Ну что теперь, укин-дукин, блукин-флукин, бликджикити-флип викет, слики-шлёпалка, дук-манкер? Джик!', 24330),
(88938, 'ruRU', '', 'Говори, демон! Где Легион держит тело Иллидана?', 24330),
(90215, 'ruRU', '', 'Тогда вкуси Косу Душ...', 24330),
(90222, 'ruRU', '', 'Я сказал, когда я отделал твоего брата до синяков, он дукнул в штаны и дал дёру. А теперь гони корм!', 24330),
(90223, 'ruRU', '', 'Эй, Ука, у тебя укер торчит наружу. Это неаппетитно и совсем негигиенично.', 24330),
(90224, 'ruRU', '', 'Твоя мамаша.', 24330),
(90231, 'ruRU', '', 'Иди манкни слики, викет. Вообще, манкни сразу двух, пока один манкает тебя сзади, а другой манкает твой дукер.', 24330),
(90232, 'ruRU', '', 'Моя голова? Да ты сам слики-башка, дук-манкер!', 24330),
(90236, 'ruRU', '', 'А ну не трогай моего брата, бликджикити дук-манкер!', 24330),
(90238, 'ruRU', '', 'Я бы хотел взглянуть на твой выбор крепких напитков.', 24330),
(90247, 'ruRU', '', 'Моя мамаша? МОЯ МАМАША?! Ах ты викет-лизун укер!', 24330),
(90311, 'ruRU', '', 'Да? Что? Этот бойцовский корм — особый семейный секрет.\n\nНи единого укинного шанса, что ты его получишь, $r.', 24330),
(90736, 'ruRU', '', 'Снова здравствуй. До нас дошли слухи о спрятанных артефактах здесь, в месте под названием Ашран. Артефакты уцелевшего клана огров Крушителей Черепов. $B$BКак думаешь, какой силой они могут обладать?$B$B', 24330),
(90901, 'ruRU', '', 'Ты оказал мне сегодня великую услугу, Фарондис.', 24330),
(90902, 'ruRU', '', 'Как жаль, что тебе не суждено ДОЖИТЬ, чтобы воспользоваться плодами моей благодарности.', 24330),
(90904, 'ruRU', '', 'Вся эта долина кишит заговорщиками и интриганами.', 24330),
(90905, 'ruRU', '', 'Якшаешься с Кенарием у меня за спиной? Я НЕ потерплю неповиновения!', 24330),
(90910, 'ruRU', '', 'Вот он, мой принц: Камень Приливов Голганнета, один из семи Камней Созидания и драгоценная реликвия калдорай.', 24330),
(91438, 'ruRU', '', 'Кто идёт? Держи руки и оружие там, где я их вижу.', 24330),
(91439, 'ruRU', '', 'Докажи мне, что ты не враг.', 24330),
(91448, 'ruRU', '', 'Ну и язык у тебя, Ука. Может, стоит забить его твоим же блукинским манк-кормом.', 24330),
(91503, 'ruRU', '', 'Твои приказы ясны! Найди Камень Приливов и верни его Её Славе, королеве Азшаре!', 24330),
(91504, 'ruRU', '', 'Эти твари лишь притворяются, что понимают его силу. Камень Приливов принадлежит Азшаре, Её Сиянию, Свету Под Волнами!', 24330),
(91505, 'ruRU', '', 'Обыщите пески!', 24330);
